contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address target, uint256 amt, bool freeze) public payable {
        // Read initial public state
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;
        uint256 totalBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 balOwnerBefore = c.balanceOf(ownerBefore); if (__ESBMC_reverted()) return;
        uint256 balTargetBefore = c.balanceOf(target); if (__ESBMC_reverted()) return;
        bool frozenBefore = c.frozenAccount(target); if (__ESBMC_reverted()) return;

        // Attempt freezeAccount
        bool frozeReverted;
        c.freezeAccount(target, freeze); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            frozeReverted = true;
        } else {
            frozeReverted = false;
        }
        bool frozenAfter = c.frozenAccount(target); if (__ESBMC_reverted()) return;

        // Attempt burn
        bool burnReverted;
        bool ok = c.burn(amt); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            burnReverted = true;
        } else {
            burnReverted = false;
        }
        uint256 totalAfterBurn = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 balOwnerAfterBurn = c.balanceOf(ownerBefore); if (__ESBMC_reverted()) return;

        // Attempt mintToken
        bool mintReverted;
        c.mintToken(target, amt); bool __rev2 = __ESBMC_reverted(); if (__rev2) {
            mintReverted = true;
        } else {
            mintReverted = false;
        }
        uint256 totalAfterMint = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 balTargetAfterMint = c.balanceOf(target); if (__ESBMC_reverted()) return;

        bool isOwner = (address(this) == ownerBefore);
        bool burn_expected_to_succeed = (balOwnerBefore >= amt) && isOwner;

        // Single assert: If caller is owner then freeze and mint must succeed and reflect changes; burn succeeds iff owner's balance >= amt and reflects change.
        // If caller is not owner then all three must have reverted and public state unchanged.
        assert(
            (
                // Owner path
                isOwner
                && frozeReverted == false
                && frozenAfter == freeze
                && mintReverted == false
                && totalAfterMint == totalBefore + amt
                && balTargetAfterMint == balTargetBefore + amt
                && (
                    (burn_expected_to_succeed && burnReverted == false && totalAfterBurn == totalBefore - amt && balOwnerAfterBurn == balOwnerBefore - amt)
                    || (!burn_expected_to_succeed && burnReverted == true && totalAfterBurn == totalBefore && balOwnerAfterBurn == balOwnerBefore)
                )
            )
            ||
            (
                // Non-owner path
                !isOwner
                && frozeReverted == true
                && frozenAfter == frozenBefore
                && burnReverted == true
                && totalAfterBurn == totalBefore
                && balOwnerAfterBurn == balOwnerBefore
                && mintReverted == true
                && totalAfterMint == totalBefore
                && balTargetAfterMint == balTargetBefore
            )
        );
    }

    receive() external payable {}
}

