    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _run(address target, uint256 amt, bool freeze) internal {
        address ownerBefore;
        try c.owner() returns (address __r) { ownerBefore = __r; } catch { return; }
        uint256 totalBefore;
        try c.totalSupply() returns (uint256 __r) { totalBefore = __r; } catch { return; }
        uint256 balOwnerBefore;
        try c.balanceOf(ownerBefore) returns (uint256 __r) { balOwnerBefore = __r; } catch { return; }
        uint256 balTargetBefore;
        try c.balanceOf(target) returns (uint256 __r) { balTargetBefore = __r; } catch { return; }
        bool frozenBefore;
        try c.frozenAccount(target) returns (bool __r) { frozenBefore = __r; } catch { return; }
        bool frozeReverted;
        try c.freezeAccount(target, freeze) {
            frozeReverted = false;
        } catch {
            frozeReverted = true;
        }
        bool frozenAfter;
        try c.frozenAccount(target) returns (bool __r) { frozenAfter = __r; } catch { return; }
        bool burnReverted;
        try c.burn(amt) returns (bool ok) {
            burnReverted = false;
        } catch {
            burnReverted = true;
        }
        uint256 totalAfterBurn;
        try c.totalSupply() returns (uint256 __r) { totalAfterBurn = __r; } catch { return; }
        uint256 balOwnerAfterBurn;
        try c.balanceOf(ownerBefore) returns (uint256 __r) { balOwnerAfterBurn = __r; } catch { return; }
        bool mintReverted;
        try c.mintToken(target, amt) {
            mintReverted = false;
        } catch {
            mintReverted = true;
        }
        uint256 totalAfterMint;
        try c.totalSupply() returns (uint256 __r) { totalAfterMint = __r; } catch { return; }
        uint256 balTargetAfterMint;
        try c.balanceOf(target) returns (uint256 __r) { balTargetAfterMint = __r; } catch { return; }
        bool isOwner = (address(this) == ownerBefore);
        bool burn_expected_to_succeed = (balOwnerBefore >= amt) && isOwner;
        assertTrue((
                // Owner path
                isOwner
                && frozeReverted == false
                && frozenAfter == freeze
                && mintReverted == false
                && totalAfterMint == totalBefore + amt
                && balTargetAfterMint == balTargetBefore + amt
                && (
                    (burn_expected_to_succeed && burnReverted == false && totalAfterBurn == totalBefore - amt && balOwnerAfterBurn == balOwnerBefore - amt)
                    || (!burn_expected_to_succeed && burnReverted == true && totalAfterBurn == totalBefore && balOwnerAfterBurn == balOwnerBefore)
                )
            )
            ||
            (
                // Non-owner path
                !isOwner
                && frozeReverted == true
                && frozenAfter == frozenBefore
                && burnReverted == true
                && totalAfterBurn == totalBefore
                && balOwnerAfterBurn == balOwnerBefore
                && mintReverted == true
                && totalAfterMint == totalBefore
                && balTargetAfterMint == balTargetBefore
            ));
    }

    function testFuzz_run(address target, uint256 amt, bool freeze) public {
        vm.assume(target.code.length == 0 && uint160(target) > 0xffff && target != address(this) && target != address(c) && target != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && target != 0x000000000000000000636F6e736F6c652e6c6f67 && target != 0x4e59b44847b379578588920cA78FbF26c0B4956C && target != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(target, amt, freeze);
    }

    receive() external payable {}
}
